import{_ as t,c as o,o as i,aj as d}from"./chunks/framework.CSCBGoZg.js";const f=JSON.parse('{"title":"Conditions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/conditions.md","filePath":"guide/conditions.md","lastUpdated":0}'),a={name:"guide/conditions.md"};function r(n,e,c,s,l,h){return i(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="conditions" tabindex="-1">Conditions <a class="header-anchor" href="#conditions" aria-label="Permalink to “Conditions”">​</a></h1><p>Conditions are used to describe when and where your pipeline and further individual pipeline steps should be run by adding them to the corresponding <code>when</code> field.</p><p>With a condition, a set of comparison values (selected from a <a href="#facts">fact</a>, <a href="/guide/variables#environment-variables">environment variable</a> or <a href="/guide/variables#runtime-variables">runtime variable</a>) is tested against a defined set of rules:</p><table tabindex="0"><thead><tr><th>Rule</th><th>Description</th></tr></thead><tbody><tr><td><code>include</code></td><td>At least one of the provided values must be contained in the set of comparison values</td></tr><tr><td><code>exclude</code></td><td>None of the provided values may be contained in the set of comparison values</td></tr><tr><td><code>match</code></td><td>At least one of the provided <a href="/guide/regex">regular expressions</a> must match at least one of the comparison values</td></tr><tr><td><code>mismatch</code></td><td>None of the provided <a href="/guide/regex">regular expressions</a> may match any of the comparison values</td></tr></tbody></table><p>If a set of comparison values is empty or a rule is empty, the condition is always met. If there are multiple rules for a single set of comparison values, those rules are combined with logical <code>AND</code>.</p><h2 id="facts" tabindex="-1">Facts <a class="header-anchor" href="#facts" aria-label="Permalink to “Facts”">​</a></h2><p>Facts are pieces of information used to provide context when checking conditions. They can relate to the environment where your pipeline is hosted, an event or arbitrary other information. A single fact can describe multiple values at once, e.g. an array of files that were changed in a specific Git commit or similar.</p><p>The following facts are provided by default:</p><table tabindex="0"><thead><tr><th>Condition</th><th>Description</th></tr></thead><tbody><tr><td><code>workerGroup</code></td><td>Available worker groups - the pipeline is executed on each matching worker group (<code>string</code>)</td></tr></tbody></table><h2 id="git-based-pipelines" tabindex="-1">Git based pipelines <a class="header-anchor" href="#git-based-pipelines" aria-label="Permalink to “Git based pipelines”">​</a></h2><p>The following facts are provided for Git based pipelines:</p><table tabindex="0"><thead><tr><th>Condition</th><th>Description</th></tr></thead><tbody><tr><td><code>trigger</code></td><td>The type of event - either a combination of <code>push</code> and <code>commit</code> or <code>tag</code>, or <code>action</code> (<code>&quot;push&quot; | &quot;commit&quot; | &quot;tag&quot; | &quot;action&quot;</code>)</td></tr><tr><td><code>action</code></td><td><a href="/guide/actions">Action</a> (available for <code>action</code> triggers) (<code>string</code>)</td></tr><tr><td><code>ref</code></td><td>Git ref of the head commit or tag, e.g. <code>refs/heads/main</code> or <code>refs/tags/v1.0.0</code> (<code>string</code>)</td></tr><tr><td><code>branch</code></td><td>Git branch (not available for <code>tag</code> triggers) (<code>string</code>)</td></tr><tr><td><code>tag</code></td><td>Git tag (available for <code>tag</code> triggers) (<code>string</code>)</td></tr><tr><td><code>file</code></td><td>Affected file(s) (available for <code>commit</code> triggers) (<code>string</code>)</td></tr><tr><td><code>repository</code></td><td>Full name of the Git repository, e.g. <code>reeveci/reeve</code></td></tr></tbody></table><p>The following default conditions apply to pipelines defined in Git repositories (e.g. using the <a href="/reference/plugin-gitea">Gitea plugin</a>):</p><ul><li>Pipelines run only on <code>commit</code> by default</li><li>Pipelines run only on the Git repository&#39;s default branch</li><li>All actions are excluded by default (this prevents your pipeline from running always if you set <code>trigger</code> to <code>action</code> but forget to add a condition for <code>action</code>)</li></ul>',14)])])}const u=t(a,[["render",r]]);export{f as __pageData,u as default};
